    };

    fn_num_5_hold: fn_number_5_hold {
        compatible = "zmk,behavior-mod-morph";
        #binding-cells = <0>;

        bindings = <&kp PRCNT>, <&kp N5>;
        mods = <(MOD_LSFT | MOD_RSFT)>;
    };

    fn_num_6_hold: fn_number_6_hold {
        compatible = "zmk,behavior-mod-morph";
        #binding-cells = <0>;

