    fn_num_0_hold: fn_number_0_hold {
        compatible = "zmk,behavior-mod-morph";
        #binding-cells = <0>;

        bindings = <&kp RPAR>, <&kp N0>;
        mods = <(MOD_LSFT | MOD_RSFT)>;
    };


    /*
     * Outer hold-taps
     *
     * Parameter 1 is a dummy value for the zero-parameter
     * hold mod-morph.
     *
     * Parameter 2 is the F-key used by the tap branch.
     */

    fn_num_1: fn_number_1 {
        compatible = "zmk,behavior-hold-tap";
        #binding-cells = <2>;

        flavor = "hold-preferred";
        tapping-term-ms = <200>;

        bindings = <&fn_num_1_hold>, <&kp>;
    };

    fn_num_2: fn_number_2 {
        compatible = "zmk,behavior-hold-tap";
        #binding-cells = <2>;

        flavor = "hold-preferred";
        tapping-term-ms = <200>;

